import { useEffect, useState, type ButtonHTMLAttributes } from 'react';
import { aiReady } from '../lib/ai';
import { Btn } from './ui';

export function useAiReady() {
  const [ready, setReady] = useState(aiReady());
  useEffect(() => {
    const f = () => setReady(aiReady());
    window.addEventListener('floppyos-ai', f);
    return () => window.removeEventListener('floppyos-ai', f);
  }, []);
  return ready;
}

/** Marks content generated by the AI (RF-121). */
export function AiBadge({ label = 'Sugerido por IA' }: { label?: string }) {
  return <span className="ai-badge">✨ {label}</span>;
}

/** ✨ button that explains itself when AI isn't configured. */
export function AiButton({ busy, children, ...p }: ButtonHTMLAttributes<HTMLButtonElement> & { busy?: boolean }) {
  const ready = useAiReady();
  return (
    <Btn small {...p} disabled={!ready || busy || p.disabled} title={ready ? p.title : 'Configura la IA en Panel de control → IA'}>
      {busy ? '✨ Pensando…' : <>✨ {children}</>}
    </Btn>
  );
}

/** Small helper for one-shot AI actions with loading + error state. */
export function useAiAction<T>() {
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [result, setResult] = useState<T | null>(null);
  const run = async (fn: () => Promise<T>) => {
    setBusy(true);
    setError(null);
    try {
      setResult(await fn());
    } catch (e) {
      setError((e as Error).message);
    }
    setBusy(false);
  };
  return { busy, error, result, setResult, run };
}
